import json
from fastcore.utils import *
from .registry import _registry

# %% ../nbs/01_behaviors.ipynb #1bb695c2
_runtime = r"""(() => {
const rules = [%s];
const by = {};
rules.forEach(r => (by[r.ev + '|' + (r.cap ? 1 : 0)] ??= []).push(r));
for (const k in by) {
  const [ev, cap] = k.split('|');
  document.addEventListener(ev, e => {
    const t = e.target;
    if (!(t instanceof Element)) return;
    for (const r of by[k]) {
      if (r.deep) {
        if (t.matches(r.sel)) r.fn(t, e);
        t.querySelectorAll(r.sel).forEach(el => r.fn(el, e));
      } else {
        const el = t.closest(r.sel);
        if (el) r.fn(el, e);
      }
    }
  }, {capture: cap === '1'});
}
})();"""

# %% ../nbs/01_behaviors.ipynb #10fe79ef
def _entry(r):
    ev = r['ev']
    if ev.startswith(':'): ev = 'htmx'+ev
    deep = ev=='htmx:load'
    return (f'{{sel: {json.dumps(r["sel"])}, ev: {json.dumps(ev)}, cap: {json.dumps(r["cap"])}, '
        f'deep: {json.dumps(deep)}, async fn(el, e) {{ {r["js"]} }}}}')

# %% ../nbs/01_behaviors.ipynb #bb776c31
def build_js():
    "The behavior script: every registered entry's behaviors, in registration order"
    return _runtime % ',\n'.join(_entry(r) for o in _registry.values() for r in o.on)
